                return orig.call(this, copy, results);
            }
            return orig.apply(this, arguments);
        };
    }
    function isKey(v) {
        if (typeof v !== "string" || !v.length) { return false; }
        for (var i = 0; i < v.length; i++) {
            var c = v.charAt(i);
            if (!((c >= "a" && c <= "z") || (c >= "0" && c <= "9") || c === "_" || c === ".")) { return false; }
        }
        return v.indexOf("_") > 0;
    }
    function tr(v) {
        var f = sim();
        if (!f || typeof f.t !== "function" || !isKey(v)) { return v; }
        var out = f.t(v);
        return (typeof out === "string" && out !== v) ? out : v;
    }
    function wrapSummary(orig) {
        return function () {
            var s = orig.apply(this, arguments);
            try {
                if (s && typeof s === "object") {
                    var names = ["performance", "performanceLabel", "message"];
                    for (var i = 0; i < names.length; i++) { if (typeof s[names[i]] === "string") { s[names[i]] = tr(s[names[i]]); } }
                    if (Array.isArray(s.insights)) {
                        for (var j = 0; j < s.insights.length; j++) {
                            var it = s.insights[j];
                            if (typeof it === "string") { s.insights[j] = tr(it); }
                            else if (it && typeof it === "object") {
                                if (typeof it.text === "string") { it.text = tr(it.text); }
                                if (typeof it.title === "string") { it.title = tr(it.title); }
                            }
                        }
                    }
                }
            } catch (e) {}
            return s;
        };
