            var _overall = Math.max(0, Math.min(100, _pct));
            var _rating = window.mySimulation.t('rating_needs_review');
            if (_overall >= 85) _rating = window.mySimulation.t('rating_excellent'); else if (_overall >= 65) _rating = window.mySimulation.t('rating_competent'); else if (_overall >= 45) _rating = window.mySimulation.t('rating_developing');
            state.domainState.score = _overall;
            state.domainState.performance = { overallScore: _overall, rating: _rating, rawScore: state.domainState.totalScore };

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                roundName: roundName,
                score: score,
                maxScore: maxScore,
                totalScore: state.domainState.totalScore,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore',
                function(v) { return v + ' pts'; });
            uiManager.bind('roundScoreDisplay', 'results.score',
                function(v) {
                    var mx = window.mySimulation.state.results ? window.mySimulation.state.results.maxScore : 0;
                    return v + '/' + mx;
                });
        }

