        getChartData(state) {
            var t = function (k) { return window.mySimulation ? window.mySimulation.t(k) : k; };
            var roundLabels = [t('roundname_abc'), t('roundname_variance'), t('roundname_zbb'), t('roundname_portfolio')];
            var data = state.domainState.scoreHistory;
            return {
                scoreChart: {
                    labels: roundLabels.slice(0, data.length),
                    datasets: [{ data: data }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var maxPossible = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results;
                if (r) {
                    totalScore += r.score || 0;
                    maxPossible += r.maxScore || 0;
                }
            }
            var pct = maxPossible > 0 ? (totalScore / maxPossible * 100) : 0;

            var performance = window.mySimulation.t('rating_needs_review');
            if (pct >= 85) performance = window.mySimulation.t('rating_excellent');
            else if (pct >= 65) performance = window.mySimulation.t('rating_competent');
            else if (pct >= 45) performance = window.mySimulation.t('rating_developing');

            var insights = [];

            if (history.length >= 4 && history[3].decisions && history[3].decisions.lineC === 3) {
                insights.push(window.mySimulation.t('insight_linec_warning'));
            }

            if (pct >= 85) {
                insights.push(window.mySimulation.t('insight_summary_excellent'));
            } else if (pct >= 65) {
                insights.push(window.mySimulation.t('insight_summary_solid'));
            } else {
                insights.push(window.mySimulation.t('insight_summary_focus'));
            }

            var overallScore = Math.max(0, Math.min(100, Math.round(pct)));
            return {
                totalScore: totalScore,
                maxPossible: maxPossible,
                percentage: Math.round(pct),
                overallScore: overallScore,
                score: overallScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.currentPeriod === 1 && results.score < 15) {
                return window.mySimulation.t('hint_abc');
            }
            if (state.currentPeriod === 2 && results.score < 12) {
                return window.mySimulation.t('hint_variance');
            }
            if (state.currentPeriod === 4 && state.decisions && state.decisions.lineC === 3) {
                return window.mySimulation.t('hint_fixedcost');
            }
            return null;
        }

